def ga(day):
    n=(date.fromisoformat(day)-LMP).days
    return dict(days=n,weeks=n//7,remaining_days=n%7,display=f'{n//7}+{n%7}')

def lab(name,value,unit,low=None,high=None,context='adult nonpregnant',reference=None):
    interval=reference if reference is not None else f'{low}-{high}'
    indicator=''
    if isinstance(value,(int,float)):
        if low is not None and value < low: indicator='L'
        if high is not None and value > high: indicator='H'
    return dict(test=name,value=value,unit=unit,reference_interval=interval,reference_low=low,reference_high=high,reference_context=context,indicator=indicator)

def add(key,day,kind,title,episode,sections,*,labs=None,findings=None,procedures=None,meds=None,prior=None,facility=None,provider=None,ref=None,tables=None,specimen=None,collected=None,gestation=False):
    facility=facility or ('lab' if kind in {'lab','cytology','screen'} else 'image' if kind=='imaging' else 'fert' if episode in {'fertility','ivf'} else 'ob' if episode=='pregnancy' else 'gp')
    provider=provider or ('lab' if facility=='lab' else 'image' if facility=='image' else 'ob' if facility=='hospital' else facility)
    default_ref={'note':'rca-note','letter':'rca-letter','lab':'jsl-easy','cytology':'lab-pap','screen':'prenatal-marker','imaging':'rca-image','procedure':'rca-procedure','embryology':'jsl-easy','prescription':'rca-rx','discharge':'rca-discharge','assessment':'fert-assessment'}
    refs=ref or [default_ref[kind]]
    d=dict(document_id=key,clinical_date=day,encounter_date=day,created_date=day,document_type=kind,title=title,episode_id=episode,sections=[dict(heading=h,text=t) for h,t in sections],laboratory_values=labs or [],findings=findings or [],procedures=procedures or [],medication_ids=meds or [],prior_document_ids=prior or [],facility_key=facility,provider_key=provider,reference_ids=refs,tables=tables or [],specimen=specimen,collection_date=collected or day)
    if gestation:d['gestational_age']=ga(day)
    DOCS.append(d)
    return key

