add('D026','2024-06-14','embryology','Day 1 fertilization report','ivf',[('Laboratory record','SYN-IVF-01, retrieval June 13. Twelve oocytes retrieved; ten mature (MII), two immature (one MI, one GV). Ten mature oocytes underwent conventional IVF. Eight show normal 2PN fertilization at day-1 assessment; two mature oocytes did not fertilize.'),('Plan','Continue culture of eight normally fertilized embryos. Blastocyst number and cryopreservation outcome remain pending. No PGT requested.')],provider='emb',prior=['D025'],findings=[dict(concept='retrieved oocytes',value=12,status='documented'),dict(concept='mature oocytes',value=10,status='documented'),dict(concept='normally fertilized 2PN',value=8,status='documented')],tables=[dict(title='Day 1 accounting',headers=['Category','Count'],rows=[['Retrieved','12'],['Mature MII','10'],['Immature MI / GV','1 / 1'],['Normal 2PN','8'],['Mature not fertilized','2']])])
add('D027','2024-06-19','embryology','Final embryo culture and cryopreservation report','ivf',[('Cycle outcome','SYN-IVF-01: 12 retrieved, 10 mature, 8 normally fertilized. Four blastocysts cryopreserved in total. Embryos E01 and E02 vitrified on day 5 (June 18); E03 and E04 on day 6 (June 19). Four other 2PN embryos arrested and were not suitable for freezing under the laboratory policy.'),('Storage','Embryos SYN-E01 to SYN-E04 each stored on an individually labelled device. No embryos transferred in this cycle. PGT not performed; morphology does not confirm chromosomal status. Witnesses Ari Quill and Rena Elm.'),('Plan','Four embryos remain stored. Review after recovery to plan a single frozen transfer.')],provider='emb',prior=['D026'],tables=[dict(title='Cryopreserved inventory',headers=['Embryo ID','Culture day','Frozen on','Gardner grade','Status'],rows=[['SYN-E01','5','2024-06-18','4AA','Stored'],['SYN-E02','5','2024-06-18','4AB','Stored'],['SYN-E03','6','2024-06-19','4BB','Stored'],['SYN-E04','6','2024-06-19','3BB','Stored']])],findings=[dict(concept='blastocysts cryopreserved',value=4,status='confirmed')])
add('D028','2024-06-25','note','Post-retrieval review','ivf',[('Subjective','Bloating resolved; withdrawal bleed began June 20 and ended June 24. No fever, severe pain or breathing symptoms.'),('Assessment','Uncomplicated recovery. No OHSS diagnosed. Final laboratory outcome June 19: 12 retrieved, 10 mature, 8 2PN, 4 blastocysts frozen.'),('Plan','Patient chooses a treatment break before November frozen transfer. No further stimulation planned. Continue folic acid; discuss transfer preparation at October review.')],prior=['D025','D027'],meds=['MED-FOLATE'])
add('D029','2024-10-25','prescription','Frozen embryo transfer preparation orders','ivf',[('Plan','Programmed single frozen transfer of day-5 embryo SYN-E01, subject to lining and pregnancy-test clearance. Last spontaneous bleeding October 27 is expected based on tracking; actual start must be confirmed before estradiol. No medication begins today.'),('Orders','Estradiol 2 mg orally three times daily from cycle day 3 after confirmed bleed, quantity 204 tablets, no repeats. Progesterone in oil 50 mg IM daily at 09:00 from November 10 only after clearance, quantity 60 daily doses, no repeats. Continue through January 4 if pregnancy confirmed; otherwise stop only after clinic review.'),('Supplement','Replace folic acid-only supplement with prenatal multivitamin containing folic acid 1 mg and iron 27 mg on November 1. Review IM injection training, medication allergies and pregnancy-test plan.')],meds=['MED-E2','MED-P4','MED-PRENATAL'],prior=['D027','D028'])
add('D030','2024-10-29','note','Frozen transfer baseline clearance','ivf',[('History','Menstrual bleeding began October 27, cycle day 3 today. Serum beta-hCG <1 IU/L. No interval illness.'),('Objective','Endometrium 3.4 mm; ovaries quiescent without cysts. Baseline estrogen 118 pmol/L.'),('Plan','Start estradiol 2 mg orally three times daily today. Return November 8 for lining assessment. Continue folic acid until switching to prenatal on November 1.')],meds=['MED-E2','MED-FOLATE'],prior=['D029'],labs=[lab('Beta-hCG','<1','IU/L',reference='<5 nonpregnant'),lab('Estradiol',118,'pmol/L',70,500,context='baseline follicular')])
add('D031','2024-11-08','imaging','Frozen transfer endometrial assessment','ivf',[('Findings','Endometrium 8.6 mm, trilaminar; no cavity fluid. Ovaries quiescent. Serum progesterone 0.8 nmol/L before supplementation.'),('Orders','Continue estradiol 2 mg three times daily. Start progesterone in oil 50 mg IM daily November 10 at 09:00. Single day-5 embryo transfer planned November 15 at 09:00 after five completed days of progesterone. Pregnancy test November 25. Plans remain contingent on clinical status.')],meds=['MED-E2','MED-P4','MED-PRENATAL'],prior=['D030'],labs=[lab('Progesterone',0.8,'nmol/L',0.2,4.5,context='before progesterone supplementation')],facility='fert',provider='fert')
add('D032','2024-11-15','procedure','Single frozen blastocyst transfer','ivf',[('Identification and embryo','SYN-FET-01. Two identifiers checked with patient and embryology witnesses Ari Quill and Rena Elm. SYN-E01, day-5 4AA blastocyst, frozen June 18, warmed today; survived with re-expansion. No PGT performed.'),('Procedure','At 09:00, ultrasound-guided atraumatic transfer of one embryo using soft catheter. Catheter check clear. No bleeding or complication. Three cryopreserved blastocysts remain: SYN-E02, SYN-E03 and SYN-E04.'),('Dating and plan','Day-5 embryo transfer gives gestational age 2+5 today; ART-equivalent LMP October 27, 2024. If pregnancy established, EDD August 3, 2025. Pregnancy is not yet confirmed. Continue estradiol and progesterone; beta-hCG November 25. Routine activity as tolerated; urgent review for severe pain or heavy bleeding.')],meds=['MED-E2','MED-P4','MED-PRENATAL'],prior=['D027','D031'],procedures=[dict(name='Frozen embryo transfer',date='2024-11-15',time='09:00',embryo_id='SYN-E01',embryo_age_days=5,number_transferred=1,remaining_frozen=3)],gestation=True)
