add('D035','2024-12-13','imaging','Early pregnancy viability ultrasound','pregnancy',[('Dating','ART dating: day-5 transfer November 15; gestation 6+5; EDD August 3, 2025. Dating retained.'),('Findings','Single intrauterine gestational sac with yolk sac and embryo. CRL 8.1 mm, approximately 6+5. Fetal cardiac activity 132/min. No subchorionic collection; no adnexal mass or free fluid.'),('Impression','Single live intrauterine pregnancy, concordant with ART dates. Early scan cannot exclude all fetal anomalies.'),('Plan','Continue estradiol and progesterone through January 4, 2025 inclusive (9+6), stop January 5 at 10+0. Arrange obstetric intake and prenatal screening counselling.')],prior=['D032','D034'],meds=['MED-E2','MED-P4','MED-PRENATAL'],gestation=True,findings=[dict(concept='single live intrauterine pregnancy',status='confirmed')])
