add('D037','2025-01-08','lab','Initial prenatal laboratory panel','pregnancy',[('Comment','O positive; antibody screen negative. Rh immune globulin is not indicated for this RhD-positive patient. Rubella result supports immunity. No significant bacteriuria. Screening results reflect specimens collected January 6.')],labs=[lab('ABO/RhD','O positive','',reference='Categorical'),lab('Antibody screen','Negative','',reference='Negative'),lab('Hemoglobin',124,'g/L',110,160,context='first trimester'),lab('MCV',88,'fL',80,100),lab('Platelets',252,'10^9/L',150,400),lab('Ferritin',32,'ug/L',15,150),lab('HIV Ag/Ab','Nonreactive','',reference='Nonreactive'),lab('HBsAg','Nonreactive','',reference='Nonreactive'),lab('Hepatitis C antibody','Nonreactive','',reference='Nonreactive'),lab('Syphilis screen','Nonreactive','',reference='Nonreactive'),lab('Rubella IgG',61,'IU/mL',10,None,reference='>=10 immune'),lab('Urine culture','No significant growth','CFU/mL',reference='No significant growth'),lab('Chlamydia NAAT','Not detected','',reference='Not detected'),lab('Gonorrhea NAAT','Not detected','',reference='Not detected')],ref=['lab-prenatal'],prior=['D036'],specimen='Serum, EDTA blood, midstream urine and urine NAAT',collected='2025-01-06',gestation=True)
