add('D052','2025-07-29','procedure','Labour and vaginal delivery record','delivery',[('Admission','Admitted July 29 at 02:10 with regular painful contractions, G1P0 at 39+2 by ART, EDD August 3. Cervix 5 cm/90%/-1. Membranes initially intact. BP 118/74, afebrile. O positive, antibody negative, GBS July 13 not isolated.'),('Labour course','Epidural placed at 04:05 without documented complication. Spontaneous rupture of membranes at 06:20, clear fluid. Continuous fetal monitoring reassuring. Full dilation 10:50; spontaneous vaginal delivery at 11:42.'),('Birth','Live singleton female newborn, ID SYN-INFANT-001, weight 3320 g. Apgar scores 8 at one minute and 9 at five minutes. Placenta delivered intact at 11:49; three-vessel cord. Second-degree perineal tear repaired. Quantified blood loss 350 mL. Oxytocin 10 IU IM after delivery at 11:45.'),('Immediate postpartum','Mother stable, uterus firm, normal lochia. Skin-to-skin and breastfeeding initiated. No postpartum hemorrhage, hypertensive disorder or neonatal resuscitation beyond routine care documented. G1P1 following birth.')],prior=['D032','D037','D050','D051'],facility='hospital',provider='ob',gestation=True,procedures=[dict(name='Spontaneous vaginal delivery',date='2025-07-29',time='11:42',gestational_days=275,infant_id='SYN-INFANT-001',birthweight_g=3320,apgar_1=8,apgar_5=9,blood_loss_ml=350),dict(name='Second-degree perineal tear repair',date='2025-07-29')],tables=[dict(title='Labour observations',headers=['Time','BP mmHg','Pulse /min','Temperature C'],rows=[['02:10','118/74','82','36.8'],['06:30','112/68','80','36.9'],['10:30','116/72','88','37.0'],['12:00','114/70','84','36.9']])])
