add('D054','2025-07-31','discharge','Maternal hospital discharge summary','postpartum',[('Admission and discharge','Admission July 29, discharge July 31. Term IVF singleton pregnancy delivered at 39+2 on July 29 at 11:42. Spontaneous vaginal delivery; second-degree tear repaired. QBL 350 mL. Infant SYN-INFANT-001 female, 3320 g, Apgar 8/9.'),('Hospital course','Afebrile, normotensive, ambulating and voiding normally. Uterus firm and bleeding appropriate. Breastfeeding with positioning support. July 30 hemoglobin 106 g/L. No postpartum hemorrhage or infection diagnosed.'),('Discharge medications','Continue prenatal vitamin daily and ferrous sulfate 300 mg every other day. Ibuprofen 400 mg every 6 hours as needed, maximum 1200 mg/day, and acetaminophen 500-1000 mg every 8 hours as needed, maximum 3000 mg/day; seven-day supply, no repeats.'),('Follow-up','Nurse call August 5 and postpartum examination September 9. Pelvic rest until comfortable and healing assessed. Seek urgent care for soaking a pad hourly, fever, chest pain, breathlessness, severe headache, unilateral leg swelling or thoughts of self-harm. Contraception discussed; condoms planned when intercourse resumes. Copy to Dr Elara Vale.')],facility='hospital',provider='ob',prior=['D052','D053'],meds=['MED-PRENATAL','MED-IRON-2','MED-IBU','MED-APAP'])
add('D055','2025-08-05','note','Postpartum nurse telephone review','postpartum',[('Subjective','Postpartum day 7. Lochia decreasing, no fever or heavy bleeding. Perineal pain improving; stopped ibuprofen and acetaminophen August 3. Breastfeeding established with occasional nipple tenderness; no red hot breast or systemic symptoms. Sleep fragmented but support available.'),('Plan','Review latch support and urgent symptoms. Continue prenatal vitamin and alternate-day iron. No depressive disorder diagnosed on this call. In-person review September 9.')],provider='nurse',facility='ob',prior=['D054'],meds=['MED-PRENATAL','MED-IRON-2'])
add('D056','2025-09-09','note','Six-week postpartum examination','postpartum',[('History','42 days after July 29 birth. G1P1. Breastfeeding, no menses since delivery. Lochia ended August 23. Mild urine leakage with cough; no dysuria, retention or prolapse symptoms. Uses condoms; pregnancy spacing discussed.'),('Examination','BP 110/68, weight 63.8 kg. Perineal repair healed. No uterine tenderness. EPDS 4/30, self-harm item 0; no depression diagnosis.'),('Plan','Refer pelvic health physiotherapy for stress leakage. Continue iron and prenatal vitamin while breastfeeding. Repeat CBC/ferritin in October. Cervical screening due under updated HPV programme; patient elects to defer collection until January 2026 after counselling.')],prior=['D052','D054','D055'],facility='ob',provider='ob',meds=['MED-PRENATAL','MED-IRON-2'],findings=[dict(concept='postpartum stress urinary incontinence',status='documented')])
add('D057','2025-10-03','assessment','Pelvic health physiotherapy assessment','postpartum',[('Subjective','Small leakage with coughing and jogging since birth. No urgency, dysuria, hematuria or pelvic pain. Breastfeeding; no menstrual return yet.'),('Examination','Consent and chaperone option documented. Pelvic floor contraction 3/5 with reduced endurance and delayed pre-cough contraction. Healed perineum; no significant prolapse observed.'),('Assessment and plan','Postpartum stress urinary incontinence. Teach coordinated pelvic floor contraction, breathing and graded return to exercise. Home practice 8 contractions held up to 6 seconds twice daily as tolerated. Reassess in November; stop if pain occurs.')],facility='physio',provider='physio',prior=['D056'],ref=['jsl-easy'])
