add('D060','2025-12-05','note','Primary-care postpartum and iron review','postpartum',[('History','Breastfeeding; infant currently four months old. Infant feeding guidance remains with the infant care team. No menstrual bleeding yet. No fatigue, urinary leakage now rare. Therapeutic iron tolerated.'),('Assessment','October 10 hemoglobin 125 g/L, ferritin 42 ug/L; resolved postpartum anemia. Continue diet after completed replenishment.'),('Plan','Last therapeutic iron dose today; stop December 6. Continue prenatal vitamin while breastfeeding. January cervical-screening visit confirmed. No additional embryo transfer planned; three embryos remain stored per fertility record.')],prior=['D058','D059','D027','D032'],meds=['MED-IRON-2','MED-PRENATAL'])
